def round_decimal_scores_to_whole_numbers(apps, schema_editor):
    """Scores/max-scores used to be Decimal(6,2); rounding here (instead of
    relying on the DB's implicit numeric->integer cast) makes the rounding
    rule explicit and identical across backends. All non-integer values in
    this database at the time this migration was written were seed/demo
    data — there was no real CITCI data to lose precision on."""
    Score = apps.get_model("grading", "Score")
    AssessmentItem = apps.get_model("grading", "AssessmentItem")
    ScoreChangeLog = apps.get_model("grading", "ScoreChangeLog")

    for score in Score.objects.exclude(score__isnull=True):
        rounded = score.score.to_integral_value(rounding=ROUND_HALF_UP)
        if rounded != score.score:
            Score.objects.filter(pk=score.pk).update(score=rounded)

    for item in AssessmentItem.objects.all():
        rounded = item.max_score.to_integral_value(rounding=ROUND_HALF_UP)
        if rounded != item.max_score:
            AssessmentItem.objects.filter(pk=item.pk).update(max_score=rounded)

    for log in ScoreChangeLog.objects.all():
        updates = {}
        if log.old_value is not None:
            rounded = log.old_value.to_integral_value(rounding=ROUND_HALF_UP)
            if rounded != log.old_value:
                updates["old_value"] = rounded
        if log.new_value is not None:
            rounded = log.new_value.to_integral_value(rounding=ROUND_HALF_UP)
            if rounded != log.new_value:
                updates["new_value"] = rounded
        if updates:
            ScoreChangeLog.objects.filter(pk=log.pk).update(**updates)


